using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.PurchaseInvoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.PurchaseInvoices.Commands.PostPurchaseInvoice;public sealed class PostPurchaseInvoiceCommandHandler(IPurchaseInvoiceRepository repository,IUserRepository users,IApplicationDbContext db):IRequestHandler<PostPurchaseInvoiceCommand,Result<PurchaseInvoiceDto>>{public async Task<Result<PurchaseInvoiceDto>>Handle(PostPurchaseInvoiceCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<PurchaseInvoiceDto>(PurchaseInvoiceErrors.NotFound);if(e.Status!="Draft")return Result.Failure<PurchaseInvoiceDto>(PurchaseInvoiceErrors.NotDraft);if(!await users.ExistsByIdAsync(request.PostedByUserId,cancellationToken))return Result.Failure<PurchaseInvoiceDto>(new Error("PurchaseInvoices.UserNotFound","The user was not found.",ErrorType.NotFound));e.Post(request.PostedByUserId,request.PostedAt);await db.SaveChangesAsync(cancellationToken);return Result.Success(PurchaseInvoiceDto.FromEntity(e));}}
